"use client";

import { usePathname, useRouter } from "next/navigation";
import { useEffect, type ReactNode } from "react";

import { useAuthStore } from "@/stores/auth-store";

/** Reserve une page aux connectes : un visiteur est envoye vers la connexion. */
export function AuthGuard({ children }: { children: ReactNode }) {
  const status = useAuthStore((s) => s.status);
  const router = useRouter();
  const pathname = usePathname();

  useEffect(() => {
    if (status === "anonymous") {
      router.replace(`/connexion?next=${encodeURIComponent(pathname)}`);
    }
  }, [status, router, pathname]);

  if (status !== "authenticated") {
    return (
      <p role="status" className="p-8 text-content-muted">
        Chargement...
      </p>
    );
  }
  return <>{children}</>;
}
import { apiClient, ApiError } from "@/lib/api-client";

export type PathSummary = {
  id: number;
  title: string;
  slug: string;
  subtitle: string;
  description: string;
  difficulty: string;
  estimated_hours: number | null;
  order: number;
};

export type LessonTitle = {
  id: number;
  title: string;
  slug: string;
  summary: string;
  order: number;
  estimated_minutes: number | null;
};

export type ModuleOutline = {
  id: number;
  title: string;
  slug: string;
  description: string;
  order: number;
  lessons: LessonTitle[];
};

export type PathDetail = PathSummary & { modules: ModuleOutline[] };

/** Revalidation ISR : la vitrine est rendue cote serveur puis mise en cache. */
const REVALIDATE = { next: { revalidate: 60 } } as RequestInit;

const byOrder = <T extends { order: number }>(items: T[]) =>
  [...items].sort((a, b) => a.order - b.order);

/** Liste publique des parcours (reponse paginee ou simple tableau). */
export async function fetchPaths(): Promise<PathSummary[]> {
  const data = await apiClient.get<PathSummary[] | { results: PathSummary[] }>(
    "learning-paths/",
    REVALIDATE,
  );
  const items = Array.isArray(data) ? data : data.results;
  return byOrder(items);
}

/** Detail d'un parcours, ou null s'il n'existe pas / n'est pas publie. */
export async function fetchPath(slug: string): Promise<PathDetail | null> {
  try {
    const path = await apiClient.get<PathDetail>(
      `learning-paths/${encodeURIComponent(slug)}/`,
      REVALIDATE,
    );
    return {
      ...path,
      modules: byOrder(path.modules).map((m) => ({
        ...m,
        lessons: byOrder(m.lessons),
      })),
    };
  } catch (error) {
    if (error instanceof ApiError && error.status === 404) return null;
    throw error;
  }
}
import Link from "next/link";
import { notFound } from "next/navigation";

import { fetchPath, type PathDetail } from "@/lib/catalogue";

export const revalidate = 60;

type Props = { params: Promise<{ slug: string }> };

export default async function PathDetailPage({ params }: Props) {
  const { slug } = await params;
  let path: PathDetail | null;
  try {
    path = await fetchPath(slug);
  } catch {
    return (
      <section className="py-12">
        <p role="alert" className="text-content-secondary">
          Impossible de charger ce parcours pour le moment. Reessayez dans un instant.
        </p>
      </section>
    );
  }
  if (!path) notFound();

  return (
    <section className="py-12">
      <Link href="/catalogue" className="text-sm text-accent hover:underline">
        Retour au catalogue
      </Link>
      <h1 className="mt-3 text-3xl font-semibold text-content-primary">{path.title}</h1>
      {path.subtitle && <p className="mt-2 text-content-secondary">{path.subtitle}</p>}
      {path.description && (
        <p className="mt-4 max-w-2xl text-content-secondary">{path.description}</p>
      )}
      {path.modules.length === 0 ? (
        <p className="mt-8 text-content-secondary">Le contenu de ce parcours arrive bientot.</p>
      ) : (
        <ol className="mt-8 flex flex-col gap-6">
          {path.modules.map((module) => (
            <li key={module.id}>
              <h2 className="text-xl font-semibold text-content-primary">{module.title}</h2>
              {module.description && (
                <p className="mt-1 text-content-secondary">{module.description}</p>
              )}
              <ol className="mt-3 list-decimal pl-6 text-content-secondary">
                {module.lessons.map((lesson) => (
                  <li key={lesson.id}>{lesson.title}</li>
                ))}
              </ol>
            </li>
          ))}
        </ol>
      )}
    </section>
  );
}
